#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import hashlib
import json
from pathlib import Path

PAYLOAD = json.loads(r'''{"213_apply_ion_transaction_trace.py":{"sha256":"9a3d3be34994172a73b5219e5789937e14dbf77c12b8db158bedc2d98e64dade","gzip_b64":""},"213_ci.sh":{"sha256":"684789cc7f9a462097d21721b6a495d1ff527423a89297400058cd5a3ac7176f","gzip_b64":""}}''')
TARGETS = {
    "213_apply_ion_transaction_trace.py": Path("scripts/213_apply_ion_transaction_trace.py"),
    "213_ci.sh": Path("scripts/213_ci.sh"),
}


def materialize() -> None:
    for name, target in TARGETS.items():
        entry = PAYLOAD[name]
        data = gzip.decompress(base64.b64decode(entry["gzip_b64"]))
        digest = hashlib.sha256(data).hexdigest()
        if digest != entry["sha256"]:
            raise SystemExit(f"{name} checksum mismatch: {digest}")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)
        if target.suffix == ".sh":
            target.chmod(0o755)
        print(f"wrote {target} sha256={digest} bytes={len(data)}")


def verify() -> None:
    for name, target in TARGETS.items():
        if not target.is_file():
            raise SystemExit(f"missing generated file: {target}")
        digest = hashlib.sha256(target.read_bytes()).hexdigest()
        expected = PAYLOAD[name]["sha256"]
        if digest != expected:
            raise SystemExit(f"{target} checksum mismatch: {digest} != {expected}")
        print(f"verified {target} sha256={digest}")


if __name__ == "__main__":
    materialize()
    verify()
